'use server';

import { revalidatePath } from 'next/cache';
import fs from 'fs/promises';
import path from 'path';

const dbPath = path.join(process.cwd(), 'data', 'db.json');

export async function toggleNotificationPreference() {
  try {
    const fileContent = await fs.readFile(dbPath, 'utf-8');
    const data = JSON.parse(fileContent);
    const newState = !data.notificationsEnabled;

    await fs.writeFile(dbPath, JSON.stringify({ notificationsEnabled: newState }, null, 2));

    revalidatePath('/');
    return { success: true, enabled: newState };
  } catch (error) {
    console.error('Failed to toggle preference:', error);
    return { success: false, error: 'Failed to update preference' };
  }
}

export async function getNotificationPreference() {
  try {
    const fileContent = await fs.readFile(dbPath, 'utf-8');
    const data = JSON.parse(fileContent);
    return data.notificationsEnabled;
  } catch (error) {
    // default to false if file read fails
    return false;
  }
}

