import fs from 'fs/promises';
import path from 'path';

const dbPath = path.join(process.cwd(), 'data', 'db.json');

export async function getNotificationPreference(): Promise<boolean> {
  try {
    const fileContent = await fs.readFile(dbPath, 'utf-8');
    const data = JSON.parse(fileContent);
    return !!data.notificationsEnabled;
  } catch (error) {
    console.error('Failed to read preference:', error);
    return false; // Default to false
  }
}

export async function updateNotificationPreference(enabled: boolean): Promise<void> {
  await fs.writeFile(dbPath, JSON.stringify({ notificationsEnabled: enabled }, null, 2));
}

