import { getNotificationPreference } from './lib/db';
import { toggleNotificationPreference } from './actions';

export default async function Home() {
  const notificationsEnabled = await getNotificationPreference();

  return (
    <main style={{ padding: '2rem', fontFamily: 'system-ui' }}>
      <h1>Settings</h1>
      <div style={{ marginBottom: '1rem' }}>
        <p>Current Notification Status: <strong>{notificationsEnabled ? 'Enabled' : 'Disabled'}</strong></p>
      </div>

      <form action={toggleNotificationPreference}>
        <button 
          type="submit"
          style={{
            padding: '0.5rem 1rem',
            background: notificationsEnabled ? '#cc0000' : '#0066cc',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: 'pointer'
          }}
        >
          {notificationsEnabled ? 'Disable Notifications' : 'Enable Notifications'}
        </button>
      </form>
    </main>
  );
}

